'use strict';
// Caller owns the existing disposable history-profile identity pool and deadline.
// A directory of symlinks selects the predecessor; no source bytes are copied.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const NAME='0124_graph_presentation_snapshot.sql',PREVIOUS='0123_ctf_canonical_admin_policy.sql',SOURCE=path.resolve(__dirname,'../..');
const packetProbe=require('./dpiPolicyPacketMigration');
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
function snapshot(blocks=1){return {version:'workshop-result-presentation-v1',narrativeSource:'fixture',errorCode:null,narrativeSha256:'a'.repeat(64),responseSha256:'b'.repeat(64),blocks:Array.from({length:blocks},(_,index)=>({index,tool:'search_products',effectKey:'owned:tool:'+index,resultSha256:'c'.repeat(64),displaySha256:'d'.repeat(64)}))};}
function boundarySnapshot(worst=false){const value=snapshot(4);value.blocks=value.blocks.map((b,index)=>({...b,tool:worst?'a'.repeat(128):'remove_from_reading_list',effectKey:worst?'ࠀ'.repeat(511)+index:'k'.repeat(128)+':tool:'+index+':remove_from_reading_list:'+String(index).repeat(64)}));return value;}
function invalidSnapshots(){const rows=[{id:'json-null',value:null},{id:'array',value:[]},{id:'scalar',value:'no'}];for(const [id,mutate]of [
 ['missing-version',p=>delete p.version],['extra-payload',p=>p.rawResponse='not admitted'],['null-source',p=>p.narrativeSource=null],['unknown-source',p=>p.narrativeSource='fallback'],['null-blocks',p=>p.blocks=null],['extra-block',p=>p.blocks[0].raw='not admitted'],['missing-effect',p=>delete p.blocks[0].effectKey],['null-block',p=>p.blocks[0]=null],['string-index',p=>p.blocks[0].index='0'],['wrong-index',p=>p.blocks[0].index=1],['fraction-index',p=>p.blocks[0].index=.5],['duplicate-effect',p=>p.blocks.push({...p.blocks[0],index:1})],['empty-effect',p=>p.blocks[0].effectKey=''],['long-effect',p=>p.blocks[0].effectKey='a'.repeat(513)],['utf16-effect',p=>p.blocks[0].effectKey='😀'.repeat(257)],['control-effect',p=>p.blocks[0].effectKey='a\nb'],['tool-syntax',p=>p.blocks[0].tool='bad-tool'],['null-hash',p=>p.narrativeSha256=null],['invalid-hash',p=>p.blocks[0].resultSha256='f'.repeat(63)],['numeric-error',p=>p.errorCode=1],['unknown-error',p=>p.errorCode='UNKNOWN'],['too-many-blocks',p=>p.blocks=snapshot(5).blocks],
 ]){const value=snapshot();mutate(value);rows.push({id,value});}return rows;}
function migrationPlan(pins){const directory=path.join(SOURCE,'db/postgres/identity-migrations');const names=fs.readdirSync(directory).filter(n=>/^\d{4}_[a-z0-9_]+\.sql$/.test(n)&&n<=PREVIOUS).sort();assert.equal(names.at(-1),PREVIOUS);return names.map(name=>{const file=path.join(directory,name),relative=path.relative(SOURCE,file);assert.equal(fs.realpathSync(file),file);assert(fs.lstatSync(file).isFile());assert.equal(sha(fs.readFileSync(file)),pins[relative],'Migration is not captured exactly');return {name,file,sha256:pins[relative]};});}
async function qualify({runtime,migration,viewRoot,sourcePins}){
 assert.equal(process.env.PG_TEST_DISPOSABLE,'yes');const r=(await runtime.query('SELECT current_user role,current_database() database')).rows[0],m=(await migration.query('SELECT current_user role,current_database() database')).rows[0];assert.equal(r.role,'dvaia_identity_runtime');assert.equal(m.role,'dvaia_identity_migration');assert.equal(r.database,m.database);assert.match(r.database,/^owasp_ai_goat_test_codebot_parity_[a-f0-9]{12}_identity$/);
 assert.equal(fs.realpathSync(viewRoot),viewRoot);const stat=fs.lstatSync(viewRoot);assert(stat.isDirectory()&&stat.uid===process.getuid()&&(stat.mode&0o777)===0o700);assert.equal(path.basename(viewRoot),'runtime');assert.equal(path.dirname(path.dirname(viewRoot)),path.join(SOURCE,'backups/private-recovery/codebot-parity'));
 const directory=path.join(SOURCE,'db/postgres/identity-migrations'),file=path.join(directory,NAME);assert.equal(sha(fs.readFileSync(file)),sourcePins[path.relative(SOURCE,file)]);const packetFile=path.join(directory,packetProbe.NAME);assert.equal(sha(fs.readFileSync(packetFile)),sourcePins[path.relative(SOURCE,packetFile)]);
 const view=path.join(viewRoot,'presentation-predecessor-view');fs.mkdirSync(view,{mode:0o700});for(const row of migrationPlan(sourcePins)){fs.symlinkSync(row.file,path.join(view,row.name));assert.equal(fs.realpathSync(path.join(view,row.name)),row.file);}
 const {migrate}=require('../../db/postgres/migrate');await migrate(migration,view);
 const ledger=async()=>(await migration.query('SELECT name,checksum,applied_at::text FROM dvaia_migrations.ledger ORDER BY name')).rows;
 const beforeLedger=await ledger(),runId=crypto.randomUUID(),owner='PRESENTATION:owned:'+crypto.randomUUID();
 await runtime.query('INSERT INTO graph_runtime.owners(owner_key) VALUES($1)',[owner]);await runtime.query("INSERT INTO graph_runtime.runs(run_id,owner_key,generation,status) VALUES($1,$2,0,'completed')",[runId,owner]);
 await runtime.query("INSERT INTO graph_runtime.events(run_id,owner_key,sequence,node,event_type,metadata) VALUES($1,$2,1,'legacy','node_end',$3::jsonb)",[runId,owner,JSON.stringify({responseSource:'fixture',durationMs:1})]);
 const readSentinel=async()=>(await runtime.query('SELECT to_jsonb(e) row FROM graph_runtime.events e WHERE run_id=$1 AND sequence=1',[runId])).rows;const before=await readSentinel();const packetState=await packetProbe.beforeUpgrade({runtime,migration});
 assert.deepEqual(await migrate(migration,directory),[NAME,packetProbe.NAME]);assert.deepEqual(await readSentinel(),before);const upgraded=await ledger();assert.deepEqual(upgraded.slice(0,-2),beforeLedger);assert.deepEqual(upgraded.slice(-2).map(row=>({name:row.name,checksum:row.checksum})),[{name:NAME,checksum:sourcePins[path.relative(SOURCE,file)]},{name:packetProbe.NAME,checksum:sourcePins[path.relative(SOURCE,packetFile)]}]);const gradePacketProbe=await packetProbe.afterUpgrade({runtime,state:packetState});
 assert.equal((await runtime.query('SELECT graph_runtime.valid_presentation_snapshot(NULL::jsonb) valid')).rows[0].valid,false);
 let sequence=2,accepted=0,rejected=0;
 async function insert(metadata){return runtime.query("INSERT INTO graph_runtime.events(run_id,owner_key,sequence,node,event_type,metadata) VALUES($1,$2,$3,'presentation','node_end',$4::jsonb)",[runId,owner,sequence++,JSON.stringify(metadata)]);}
 const valid=[snapshot(0),snapshot(1),snapshot(4),boundarySnapshot(),boundarySnapshot(true),{...snapshot(),narrativeSource:'model',errorCode:'MODEL_OUTPUT_LIMIT'},{...snapshot(),narrativeSource:'unavailable',errorCode:'MODEL_RESPONSE_UNAVAILABLE'}];
 for(const value of valid){assert.equal((await runtime.query('SELECT graph_runtime.valid_presentation_snapshot($1::jsonb) valid',[JSON.stringify(value)])).rows[0].valid,true);await insert({presentationSnapshot:value});accepted++;}
 for(const row of invalidSnapshots()){assert.equal((await runtime.query('SELECT graph_runtime.valid_presentation_snapshot($1::jsonb) valid',[JSON.stringify(row.value)])).rows[0].valid,false,row.id);await assert.rejects(insert({presentationSnapshot:row.value}),{code:'23514'});rejected++;}
 for(const metadata of [{rawResponse:'denied'},{provider:'a'.repeat(161)},{promptPolicySnapshot:null},{policyAdmission:null}]){await assert.rejects(insert(metadata),{code:'23514'});rejected++;}
 const oversized=Object.fromEntries(['decisionSource','tool','provider','model','tokens','durationMs','attempt','errorCode','objectiveId','rubricVersion','judgeVersion','judgePolicyDigest','contextTokens','verdict','evidenceSummary'].map(k=>[k,'a'.repeat(160)]));
 for(const metadata of [oversized,{...oversized,presentationSnapshot:snapshot()}]){await assert.rejects(insert(metadata),{code:'23514',constraint:'events_metadata_size_check'});rejected++;}

 const privileges=(await runtime.query("SELECT has_function_privilege(current_user,'graph_runtime.valid_presentation_snapshot(jsonb)','EXECUTE') runtime_allowed,NOT EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a WHERE p.oid='graph_runtime.valid_presentation_snapshot(jsonb)'::regprocedure AND a.grantee=0 AND a.privilege_type='EXECUTE') public_denied")).rows[0];assert.deepEqual(privileges,{runtime_allowed:true,public_denied:true});
 const events=(await runtime.query('SELECT to_jsonb(e) row FROM graph_runtime.events e WHERE run_id=$1 ORDER BY sequence',[runId])).rows;assert.equal(events.length,accepted+1);assert.deepEqual(await migrate(migration,directory),[]);assert.deepEqual(await ledger(),upgraded);assert.deepEqual((await runtime.query('SELECT to_jsonb(e) row FROM graph_runtime.events e WHERE run_id=$1 ORDER BY sequence',[runId])).rows,events);
 assert.deepEqual(await packetState.read(),packetState.sentinel);gradePacketProbe.noOp=true;
 return {gradePacketProbe,migration:NAME,populatedUpgrade:true,priorLedgerChecksumsPreserved:true,priorTracePreserved:true,runtimeGrants:true,publicExecuteDenied:true,sqlNullDenied:true,accepted,rejected,noOp:true,supported128PrefixFourBlocks:true,worstUnicodeEnvelope:true,legacyMetadataBoundPreserved:true,freshInitialization:false};
}
module.exports={NAME,PREVIOUS,snapshot,boundarySnapshot,invalidSnapshots,migrationPlan,qualify};
